from __future__ import annotations

"""Domain models for experience allocation in an A/B/n activity.

An *activity* is one experiment. It has a fixed ``bucket_count`` (default 10000)
and an activity-specific ``salt``. Each *variant* (experience) carries a target
``weight`` as a percentage; the weights of active variants sum to 100.

The mapping that actually decides who sees what is the *bucket allocation*: a
list of bucket ranges, each owned by one variant. A visitor hashes to a bucket,
the bucket belongs to a range, the range names a variant. That mapping is what
must stay stable when variants are added or removed, so it is persisted rather
than recomputed from the current variant list on every read.

The objects here are plain value objects. Allocation math, persistence, and
resolution live in the other layers.
"""

from dataclasses import dataclass, field, replace


CONTROL_VARIANT = "control"


def _require_text(value: str, field_name: str) -> None:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field_name} is required")


def _require_weight(value: float, field_name: str) -> None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{field_name} must be a number")
    if value < 0:
        raise ValueError(f"{field_name} must be non-negative")
    if value > 100:
        raise ValueError(f"{field_name} cannot exceed 100")


@dataclass(frozen=True)
class Variant:
    """One experience in an activity, with a target traffic ``weight``."""

    variant_id: str
    weight: float
    label: str = ""

    def __post_init__(self) -> None:
        _require_text(self.variant_id, "variant_id")
        _require_weight(self.weight, "weight")

    def with_weight(self, weight: float) -> "Variant":
        return replace(self, weight=weight)


@dataclass(frozen=True)
class BucketRange:
    """A half-open ``[start, end)`` run of buckets owned by one variant.

    Ranges never overlap within an activity. The set of all ranges does not
    have to cover every bucket: buckets outside every range are *unallocated*
    and form the donor pool a newly added variant draws from.
    """

    variant_id: str
    start: int
    end: int

    def __post_init__(self) -> None:
        _require_text(self.variant_id, "variant_id")
        if not isinstance(self.start, int) or isinstance(self.start, bool):
            raise ValueError("start must be an int")
        if not isinstance(self.end, int) or isinstance(self.end, bool):
            raise ValueError("end must be an int")
        if self.start < 0:
            raise ValueError("start must be non-negative")
        if self.end < self.start:
            raise ValueError("end must be >= start")

    def width(self) -> int:
        return self.end - self.start

    def contains(self, bucket: int) -> bool:
        return self.start <= bucket < self.end

    def shifted(self, start: int, end: int) -> "BucketRange":
        return BucketRange(variant_id=self.variant_id, start=start, end=end)


@dataclass(frozen=True)
class Activity:
    """One experiment, identified by ``activity_id`` with a fixed bucket space."""

    activity_id: str
    salt: str
    variants: tuple[Variant, ...] = ()
    bucket_count: int = 10000
    exclusion_group: str | None = None

    def __post_init__(self) -> None:
        _require_text(self.activity_id, "activity_id")
        if not isinstance(self.salt, str) or not self.salt:
            raise ValueError("salt is required")
        if not isinstance(self.bucket_count, int) or isinstance(self.bucket_count, bool):
            raise ValueError("bucket_count must be an int")
        if self.bucket_count <= 0:
            raise ValueError("bucket_count must be positive")

    def variant_ids(self) -> list[str]:
        return [variant.variant_id for variant in self.variants]

    def find_variant(self, variant_id: str) -> Variant | None:
        for variant in self.variants:
            if variant.variant_id == variant_id:
                return variant
        return None

    def total_weight(self) -> float:
        return sum(variant.weight for variant in self.variants)

    def with_variants(self, variants: tuple[Variant, ...]) -> "Activity":
        return replace(self, variants=variants)


@dataclass(frozen=True)
class BucketAllocation:
    """The persisted bucket->variant map for one activity.

    This is the authoritative record. Once a bucket is assigned to a variant,
    that bucket keeps its variant until the variant is removed. Adding a new
    variant only consumes unallocated buckets; it must never reassign a bucket
    that already belongs to a surviving variant.
    """

    activity_id: str
    bucket_count: int
    ranges: tuple[BucketRange, ...] = ()
    revision: int = 0

    def __post_init__(self) -> None:
        _require_text(self.activity_id, "activity_id")
        if self.bucket_count <= 0:
            raise ValueError("bucket_count must be positive")

    def variant_ids(self) -> list[str]:
        seen: list[str] = []
        for rng in self.ranges:
            if rng.variant_id not in seen:
                seen.append(rng.variant_id)
        return seen

    def ranges_for(self, variant_id: str) -> list[BucketRange]:
        return [rng for rng in self.ranges if rng.variant_id == variant_id]

    def allocated_count(self) -> int:
        return sum(rng.width() for rng in self.ranges)

    def unallocated_count(self) -> int:
        return self.bucket_count - self.allocated_count()

    def variant_for_bucket(self, bucket: int) -> str | None:
        """Return the variant owning ``bucket``, or ``None`` if unallocated."""

        for rng in self.ranges:
            if rng.contains(bucket):
                return rng.variant_id
        return None

    def width_by_variant(self) -> dict[str, int]:
        widths: dict[str, int] = {}
        for rng in self.ranges:
            widths[rng.variant_id] = widths.get(rng.variant_id, 0) + rng.width()
        return widths

    def with_ranges(self, ranges: tuple[BucketRange, ...]) -> "BucketAllocation":
        return BucketAllocation(
            activity_id=self.activity_id,
            bucket_count=self.bucket_count,
            ranges=ranges,
            revision=self.revision + 1,
        )


@dataclass
class AssignmentResult:
    """The outcome of resolving one visitor against one activity."""

    activity_id: str
    visitor_id: str
    variant_id: str | None
    bucket: int
    status: str = "assigned"
    reason: str = ""
    excluded_by: str | None = None
    fields: dict = field(default_factory=dict)

    def is_assigned(self) -> bool:
        return self.status == "assigned" and self.variant_id is not None


def free_buckets(allocation: BucketAllocation) -> list[int]:
    """List every bucket not covered by any range, in ascending order."""

    owned = [False] * allocation.bucket_count
    for rng in allocation.ranges:
        for bucket in range(rng.start, min(rng.end, allocation.bucket_count)):
            owned[bucket] = True
    return [bucket for bucket, taken in enumerate(owned) if not taken]

