from __future__ import annotations

"""Build and persist the bucket->variant map for an activity.

The initial allocation lays variants out as contiguous bucket runs sized by
weight. After that, the persisted ``BucketAllocation`` is the authority: callers
read it to find a bucket's variant, and the allocation manager mutates it when
variants are added or removed.

The key invariant this layer protects: once a bucket belongs to a variant, that
bucket's owner only changes if the variant itself is removed. Reweighting an
existing variant or adding a new one must not move a surviving variant's
buckets, because doing so would silently re-assign live visitors.
"""

from allocation_models import (
    Activity,
    BucketAllocation,
    BucketRange,
    Variant,
)


def _weighted_widths(variants: list[Variant], bucket_count: int) -> list[int]:
    """Split ``bucket_count`` buckets across variants by weight.

    A weight is a share of 100, so a variant gets ``weight/100`` of the bucket
    space. Weights that sum to less than 100 leave a tail of buckets unallocated
    (the donor pool); weights summing to 100 cover the whole space. A
    largest-remainder pass keeps the integer widths close to the real shares.
    """

    if not variants:
        return []

    raw = [v.weight / 100.0 * bucket_count for v in variants]
    floors = [int(x) for x in raw]
    target_total = min(bucket_count, sum(floors) + _remainder_budget(raw, floors, bucket_count))

    remainder = target_total - sum(floors)
    if remainder <= 0:
        return floors

    # Hand the leftover buckets to the variants with the largest fractional part.
    order = sorted(
        range(len(variants)),
        key=lambda i: raw[i] - floors[i],
        reverse=True,
    )
    for i in range(remainder):
        floors[order[i % len(order)]] += 1
    return floors


def _remainder_budget(raw: list[float], floors: list[int], bucket_count: int) -> int:
    """How many leftover buckets the rounded shares are owed.

    The real shares sum to ``sum(raw)`` buckets; the floors fall short by the
    rounded total. That shortfall is the number of buckets to hand back out,
    capped so we never exceed the bucket space.
    """

    rounded_total = round(sum(raw))
    return max(0, rounded_total - sum(floors))


def build_initial_allocation(activity: Activity) -> BucketAllocation:
    """Lay the activity's variants out as contiguous bucket ranges.

    Variants are placed in declaration order starting at bucket 0. The sum of
    widths equals the bucket count when weights sum to 100, leaving no donor
    pool; if weights sum to less than 100 the tail buckets stay unallocated.
    """

    variants = list(activity.variants)
    widths = _weighted_widths(variants, activity.bucket_count)

    ranges: list[BucketRange] = []
    cursor = 0
    for variant, width in zip(variants, widths):
        if width <= 0:
            continue
        end = cursor + width
        ranges.append(BucketRange(variant_id=variant.variant_id, start=cursor, end=end))
        cursor = end

    return BucketAllocation(
        activity_id=activity.activity_id,
        bucket_count=activity.bucket_count,
        ranges=tuple(ranges),
        revision=0,
    )


def realized_split(allocation: BucketAllocation) -> dict[str, float]:
    """Fraction of the bucket space each variant currently owns."""

    widths = allocation.width_by_variant()
    return {
        variant_id: width / allocation.bucket_count
        for variant_id, width in widths.items()
    }


def coverage(allocation: BucketAllocation) -> float:
    """Fraction of the bucket space that is allocated to some variant."""

    return allocation.allocated_count() / allocation.bucket_count


def assert_no_overlap(allocation: BucketAllocation) -> None:
    """Raise if any two ranges overlap. Used as a defensive self-check."""

    ordered = sorted(allocation.ranges, key=lambda r: r.start)
    for earlier, later in zip(ordered, ordered[1:]):
        if later.start < earlier.end:
            raise ValueError(
                f"overlapping ranges: {earlier.variant_id} and {later.variant_id}"
            )


class AllocationStore:
    """Persists one ``BucketAllocation`` per activity id.

    Reads return the stored map as-is. The whole point of persisting is that the
    map survives variant-list changes; resolution always goes through what is
    stored here rather than recomputing from the live variant list.
    """

    def __init__(self) -> None:
        self._by_activity: dict[str, BucketAllocation] = {}

    def seed(self, allocation: BucketAllocation) -> BucketAllocation:
        self._by_activity[allocation.activity_id] = allocation
        return allocation

    def save(self, allocation: BucketAllocation) -> BucketAllocation:
        self._by_activity[allocation.activity_id] = allocation
        return allocation

    def get(self, activity_id: str) -> BucketAllocation | None:
        return self._by_activity.get(activity_id)

    def require(self, activity_id: str) -> BucketAllocation:
        allocation = self._by_activity.get(activity_id)
        if allocation is None:
            raise KeyError(f"no allocation for activity {activity_id}")
        return allocation

    def contains(self, activity_id: str) -> bool:
        return activity_id in self._by_activity

    def revision(self, activity_id: str) -> int:
        allocation = self._by_activity.get(activity_id)
        if allocation is None:
            return -1
        return allocation.revision

    def known_activities(self) -> list[str]:
        return list(self._by_activity)

    def snapshot_widths(self, activity_id: str) -> dict[str, int]:
        allocation = self._by_activity.get(activity_id)
        if allocation is None:
            return {}
        return allocation.width_by_variant()

