"""Public dictionary views of allocations and assignment results."""

from allocation_models import AssignmentResult, BucketAllocation
from bucket_map import coverage, realized_split


def allocation_to_dict(allocation: BucketAllocation) -> dict[str, object]:
    return {
        "activity_id": allocation.activity_id,
        "bucket_count": allocation.bucket_count,
        "revision": allocation.revision,
        "variant_ids": allocation.variant_ids(),
        "width_by_variant": allocation.width_by_variant(),
        "allocated": allocation.allocated_count(),
        "unallocated": allocation.unallocated_count(),
        "coverage": coverage(allocation),
        "realized_split": realized_split(allocation),
        "ranges": [
            {"variant_id": r.variant_id, "start": r.start, "end": r.end}
            for r in allocation.ranges
        ],
    }


def assignment_to_dict(result: AssignmentResult) -> dict[str, object]:
    payload: dict[str, object] = {
        "activity_id": result.activity_id,
        "visitor_id": result.visitor_id,
        "variant_id": result.variant_id,
        "bucket": result.bucket,
